// @sourcefile .\Src\glSmack.cpp
void __fastcall DecodeSmacker(char * szSmacker, D2SmackerContextStrc * pBuffer, int32_t nVersion) {
    void* nSmackHandle;
    int iVar1;
    uint8_t* pPalDst;
    int nRowIdx;
    uint8_t abPalBuf[768];
    uint8_t abImgBuf[1024];
    uint32_t nImgBpp;
    uint32_t nImgHeight;
    uint32_t nImgWidth;
    DWORD dwFileSize;
    if (!gpGlideSmackerTexBuf2) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x8e);
      exit(-1);
    }

    memset(gpGlideSmackerTexBuf2, 0, 0x8000);
    memset(gpGlideSmackerTexBuf0, 0, 0x8000);
    memset(gpGlideSmackerTexBuf1, 0, 0x8000);
    if (!gnRenderState) {
      GLSMACK_UploadTextures();
    }

    pBuffer->eMode = (char)nVersion;
    if ((char)nVersion != 'p') {
      if ((char)nVersion != 's') {
        return;
      }
      if (pBuffer->hSmack) {
        return;
      }

      nSmackHandle = (void*)SmackOpen(szSmacker, 0xfe000, -1);
      pBuffer->hSmack = nSmackHandle;
      if (nSmackHandle) {
        SmackToBuffer(nSmackHandle, 0, 0, 0x200, 0x40, gpGlideSmackerTexBuf2, 0);
        return;
      }
    } else {
      uint32_t bFileLoadOk;
      nVersion = 0;
      dwFileSize = 0;
      bFileLoadOk = Storm::Source::SFile::SFileLoadFileEx(nullptr, szSmacker, (void**)&nVersion, &dwFileSize, 0, 3, 0);
      if (bFileLoadOk && nVersion) {
        iVar1 = Storm::Source::SBMP::SBmpDecodeImage(2, (void*)nVersion, dwFileSize, abImgBuf, *gpGlideSmackerTexBuf2, 0x6db0, &nImgWidth, &nImgHeight, &nImgBpp);
        Storm::Source::SMem::SMemFree((void*)nVersion, ".\\Src\\glSmack.cpp", 0xdb, 0);
        bFileLoadOk = nImgWidth;
        if (iVar1 && nImgWidth == 0x1d4 && nImgHeight == 0x3c && nImgBpp == 8) {
          iVar1 = 0;
          pPalDst = abPalBuf + 1;
          do {
            pPalDst[-1] = abImgBuf[iVar1 * 4];
            *pPalDst = abImgBuf[iVar1 * 4 + 1];
            pPalDst[1] = abImgBuf[iVar1 * 4 + 2];
            iVar1++;
            pPalDst += 3;
          } while (iVar1 < 0x100);

          nRowIdx = 0x3b;
          iVar1 = 0x7600;
          do {
            memmove(*gpGlideSmackerTexBuf2 + iVar1, *gpGlideSmackerTexBuf2 + nRowIdx * bFileLoadOk, bFileLoadOk);
            iVar1 += -0x200;
            nRowIdx--;
            bFileLoadOk = nImgWidth;
          } while (iVar1 > 0);

          GLSMACK_ConvertPaletteToRGB565(abPalBuf);
          GLSMACK_UploadTextures();
          return;
        }
      }
    }
    if (pBuffer->eMode == 's' && pBuffer->hSmack) {
      SmackClose(pBuffer->hSmack);
      pBuffer->hSmack = 0;
    }

    pBuffer->eMode = '\0';
}

void __fastcall PlayerSmacker(D2SmackerContextStrc * pContext) {
    void* hSmack;
    if (pContext->eMode != 'p') {
      int bWaiting;
      if (pContext->eMode != 's') {
        return;
      }

      hSmack = pContext->hSmack;
      if (!hSmack) {
        return;
      }

      bWaiting = SmackWait(hSmack);
      if (!bWaiting) {
        if (!gnGlideWindowHandle) {
          return;
        }

        SmackDoFrame(hSmack);
        if (*(int*)((int)hSmack + 0x374) == *(int*)((int)hSmack + 0xc)) {
          Glide::CloseSmacker(pContext);
        } else {
          SmackNextFrame(hSmack);
        }
        if (gnRenderState) {
          return;
        }

        GLSMACK_ConvertPaletteToRGB565((uint8_t*)((int)hSmack + 0x6c));
        GLSMACK_UploadTextures();
      }
      if (gnRenderState) {
        return;
      }

      GLSMACK_DrawSmackerQuad(pContext, *(int32_t*)((int)hSmack + 8), *(int32_t*)((int)hSmack + 4));
    }
    if (gnRenderState) {
      return;
    }

    GLSMACK_DrawSmackerQuad(pContext, 0x3c, 0x1d4);
}

